  // arms: pivot at shoulder (y=1.52), upper arm + forearm
  const armL = limb(shirt, 0.62, 0.085); armL.position.set(-0.32, 1.52, 0);
  const armR = limb(shirt, 0.62, 0.085); armR.position.set(0.32, 1.52, 0);
